# Realistic-finish 3D hero portraits: img2img from the chosen face + IP-Adapter style from the user's reference look.
# SDXL 1.0 (OpenRAIL++-M) + IP-Adapter SDXL (Apache-2.0). 77 tokens per encoder: character in prompt, look in prompt_2.
import subprocess, time, base64, io
t0 = time.time()
subprocess.run("pip install -q -U diffusers transformers accelerate", shell=True, timeout=900)
import torch
from diffusers import StableDiffusionXLImg2ImgPipeline, AutoencoderKL
from PIL import Image, ImageDraw
def load(s): return Image.open(io.BytesIO(base64.b64decode(s))).convert("RGB")
INIT = {"genius": load(""), "questioner": load("")}
STYLE = load("")
vae = AutoencoderKL.from_pretrained("madebyollin/sdxl-vae-fp16-fix", torch_dtype=torch.float16)
pipe = StableDiffusionXLImg2ImgPipeline.from_pretrained("stabilityai/stable-diffusion-xl-base-1.0", vae=vae,
       torch_dtype=torch.float16, variant="fp16", use_safetensors=True).to("cuda")
pipe.load_ip_adapter("h94/IP-Adapter", subfolder="sdxl_models", weight_name="ip-adapter_sdxl.bin")
LOOK = ("high-end stylized 3D character photo, oversized head, big soft bulbous nose, large glossy round eyes, "
        "fuzzy realistic hair strands, real woven fabric texture, soft window light, shallow depth of field, "
        "blurred cozy studio background, 85mm lens, ultra detailed")
NEG = ("text, logo, brand, watermark, 2d, flat, vector, drawing, sketch, deformed, extra fingers, multiple people, "
       "cropped head, blurry face, lowres, ugly, beard on genius")
HOSTS = {
  "genius": ("cartoon Indian man, thin long narrow face, warm brown skin, clean shaven, big round black glasses, "
             "worried raised eyebrows, messy curly black hair, pencil behind ear, white shirt, maroon tie, "
             "brown suspenders, khaki jacket"),
  "questioner": ("cartoon chubby Indian man, big round full face, chubby cheeks, warm brown skin, smug half smile, "
                 "relaxed half-closed eyes, thick eyebrows, short black goatee, beige baseball cap, "
                 "red and black track jacket, white t-shirt"),
}
PLAN = {"genius": [0.55, 0.7], "questioner": [0.7, 0.82]}
for name, desc in HOSTS.items():
    tiles = []
    for strength in PLAN[name]:
        for seed in [11, 12, 13]:
            pipe.set_ip_adapter_scale(0.45)
            img = pipe(prompt=desc, prompt_2=LOOK, negative_prompt=NEG, image=INIT[name], ip_adapter_image=STYLE,
                       strength=strength, num_inference_steps=40, guidance_scale=6.5,
                       generator=torch.Generator("cuda").manual_seed(seed)).images[0]
            img.save(f"/kaggle/working/{name}_s{int(strength*100)}_seed{seed}.png")
            tiles.append((f"strength {strength} seed {seed}", img))
            print(f"{name} {strength} {seed}: {time.time()-t0:.0f}s", flush=True)
    tw, th = 448, 576
    sheet = Image.new("RGB", (tw * 3, (th + 30) * 2), "white"); d = ImageDraw.Draw(sheet)
    for i, (lab, img) in enumerate(tiles):
        x, y = (i % 3) * tw, (i // 3) * (th + 30)
        d.text((x + 8, y + 8), f"{name} option {i+1} ({lab})", fill="black")
        sheet.paste(img.resize((tw, th)), (x, y + 30))
    sheet.save(f"/kaggle/working/{name}_realistic.jpg", quality=92)
print(f"TOTAL {time.time()-t0:.0f}s")
